CREATE TABLE shared_rate_limits (bucket_key VARCHAR(191) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, window_start_ms BIGINT UNSIGNED NOT NULL, accepted_count INT UNSIGNED NOT NULL DEFAULT 0, total_count INT UNSIGNED NOT NULL DEFAULT 0, expires_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (bucket_key,window_start_ms), KEY idx_shared_rate_limits_expiry (expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
